// --- Hashing de contraseñas (SHA-256 iterado con salt) -------------------
// Implementación en JS puro para que funcione aunque n8n no permita require('crypto').
function sha256(texto) {
  const utf8 = unescape(encodeURIComponent(texto));
  const K = [];
  const H = [];
  let primo = 2;
  const esPrimo = (n) => { for (let d = 2; d * d <= n; d++) if (n % d === 0) return false; return true; };
  const frac = (x) => ((x - Math.floor(x)) * 0x100000000) | 0;
  while (K.length < 64) {
    if (esPrimo(primo)) {
      if (H.length < 8) H.push(frac(Math.pow(primo, 1 / 2)));
      K.push(frac(Math.pow(primo, 1 / 3)));
    }
    primo++;
  }
  const bytes = [];
  for (let i = 0; i < utf8.length; i++) bytes.push(utf8.charCodeAt(i));
  const bitLen = bytes.length * 8;
  bytes.push(0x80);
  while (bytes.length % 64 !== 56) bytes.push(0);
  for (let i = 7; i >= 0; i--) bytes.push(i >= 4 ? 0 : (bitLen >>> (i * 8)) & 0xff);
  const rotr = (x, n) => (x >>> n) | (x << (32 - n));
  const w = new Array(64);
  for (let off = 0; off < bytes.length; off += 64) {
    for (let i = 0; i < 16; i++) {
      w[i] = (bytes[off + i * 4] << 24) | (bytes[off + i * 4 + 1] << 16) | (bytes[off + i * 4 + 2] << 8) | bytes[off + i * 4 + 3];
    }
    for (let i = 16; i < 64; i++) {
      const s0 = rotr(w[i - 15], 7) ^ rotr(w[i - 15], 18) ^ (w[i - 15] >>> 3);
      const s1 = rotr(w[i - 2], 17) ^ rotr(w[i - 2], 19) ^ (w[i - 2] >>> 10);
      w[i] = (w[i - 16] + s0 + w[i - 7] + s1) | 0;
    }
    let [a, b, c, d, e, f, g, h] = H;
    for (let i = 0; i < 64; i++) {
      const S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
      const t1 = (h + S1 + ((e & f) ^ (~e & g)) + K[i] + w[i]) | 0;
      const S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
      const t2 = (S0 + ((a & b) ^ (a & c) ^ (b & c))) | 0;
      h = g; g = f; f = e; e = (d + t1) | 0; d = c; c = b; b = a; a = (t1 + t2) | 0;
    }
    H[0] = (H[0] + a) | 0; H[1] = (H[1] + b) | 0; H[2] = (H[2] + c) | 0; H[3] = (H[3] + d) | 0;
    H[4] = (H[4] + e) | 0; H[5] = (H[5] + f) | 0; H[6] = (H[6] + g) | 0; H[7] = (H[7] + h) | 0;
  }
  return H.map((x) => (x >>> 0).toString(16).padStart(8, '0')).join('');
}

const ITERACIONES_HASH = 5000;

function hashPassword(password, salt) {
  let hash = sha256(salt + ':' + password);
  for (let i = 1; i < ITERACIONES_HASH; i++) hash = sha256(hash + salt);
  return hash;
}

function hexAleatorio(bytes) {
  try {
    return require('crypto').randomBytes(bytes).toString('hex');
  } catch (e) {
    let s = '';
    for (let i = 0; i < bytes * 2; i++) s += Math.floor(Math.random() * 16).toString(16);
    return s;
  }
}

// Comparación en tiempo constante para no filtrar información por tiempos.
function igualesSeguro(a, b) {
  if (typeof a !== 'string' || typeof b !== 'string' || a.length !== b.length) return false;
