function resolverSesion(token) {
  const t = norm(token);
  if (!t) return { ok: false, status: 401, error: 'Inicia sesión para continuar.' };
  const sesion = filas('Leer Sesiones').find((s) => s.session_token === t);
  if (!sesion) return { ok: false, status: 401, error: 'Tu sesión no es válida. Inicia sesión de nuevo.' };
  if (sesion.estado !== 'ACTIVA') return { ok: false, status: 401, error: 'Tu sesión fue cerrada. Inicia sesión de nuevo.' };
  if (new Date(sesion.expira_en).getTime() <= Date.now()) {
    return { ok: false, status: 401, error: 'Tu sesión expiró. Inicia sesión de nuevo.' };
  }
  const usuario = filas('Leer Usuarios').find((u) => u.usuario_id === sesion.usuario_id);
  if (!usuario || usuario.estado !== 'ACTIVO') {
    return { ok: false, status: 403, error: 'Esta cuenta está inactiva.' };
  }
